create table sanidad.casos_clinicos(id uuid primary key,empresa_id uuid not null references core.empresas(id),animal_id uuid not null references ganado.animales(id),fecha_inicio timestamptz not null,sintomas text not null,enfermedad_id uuid references sanidad.enfermedades(id),diagnostico_texto text,severidad varchar(20) not null,estado varchar(25) not null default 'ABIERTO',veterinario_id uuid,fecha_cierre timestamptz,resultado varchar(300),observaciones text,created_at timestamptz not null default now(),created_by uuid,updated_at timestamptz not null default now(),updated_by uuid,version bigint not null default 0,constraint ck_caso_severidad check(severidad in('LEVE','MODERADA','GRAVE','CRITICA')),constraint ck_caso_estado check(estado in('ABIERTO','EN_OBSERVACION','EN_TRATAMIENTO','CERRADO','ANULADO')));
create index idx_casos_animal on sanidad.casos_clinicos(empresa_id,animal_id,fecha_inicio desc);
create table sanidad.tratamientos(id uuid primary key,empresa_id uuid not null references core.empresas(id),caso_clinico_id uuid references sanidad.casos_clinicos(id),animal_id uuid not null references ganado.animales(id),fecha_inicio timestamptz not null,fecha_fin_estimada timestamptz not null,fecha_fin_real timestamptz,diagnostico text,veterinario_id uuid,estado varchar(20) not null default 'BORRADOR',observaciones text,created_at timestamptz not null default now(),created_by uuid,updated_at timestamptz not null default now(),updated_by uuid,version bigint not null default 0,constraint ck_tratamiento_estado check(estado in('BORRADOR','ACTIVO','FINALIZADO','SUSPENDIDO','ANULADO')));
create table sanidad.tratamiento_detalles(id uuid primary key,empresa_id uuid not null references core.empresas(id),tratamiento_id uuid not null references sanidad.tratamientos(id),producto_id uuid,lote_producto_id uuid,dosis numeric(12,3) not null,unidad_dosis varchar(30) not null,frecuencia_horas int not null,duracion_dias int not null,via_administracion varchar(60),retiro_carne_dias int not null default 0,retiro_leche_dias int not null default 0,created_at timestamptz not null default now(),constraint ck_detalle_dosis check(dosis>0),constraint ck_detalle_frecuencia check(frecuencia_horas>0),constraint ck_detalle_duracion check(duracion_dias>0));
create table sanidad.aplicaciones_tratamiento(id uuid primary key,empresa_id uuid not null references core.empresas(id),tratamiento_detalle_id uuid not null references sanidad.tratamiento_detalles(id),fecha_programada timestamptz not null,fecha_aplicada timestamptz,dosis_programada numeric(12,3) not null,dosis_aplicada numeric(12,3),aplicado_por uuid,estado varchar(20) not null default 'PENDIENTE',observaciones text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),version bigint not null default 0,constraint ck_ap_trat_estado check(estado in('PENDIENTE','APLICADA','OMITIDA','ATRASADA','CANCELADA')));
create unique index uq_ap_tratamiento_programada_activa on sanidad.aplicaciones_tratamiento(tratamiento_detalle_id,fecha_programada) where estado<>'CANCELADA';
create index idx_ap_trat_pendiente on sanidad.aplicaciones_tratamiento(empresa_id,fecha_programada) where estado in('PENDIENTE','ATRASADA');
